  const shellRoot=path.join(os.homedir(),'.cache/puppeteer/chrome-headless-shell');
  const version=fs.readdirSync(shellRoot).filter(f=>f.startsWith('win64-')).sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})).at(-1);
